section.programlisting:
@Component
@HttpJdkContextPath("/hello")
public class HelloHandler implements HttpHandler {

    @Override
    public void handle(HttpExchange exchange) throws IOException {
        byte[] body = "Hello, OSGi!".getBytes(StandardCharsets.UTF_8);
        exchange.sendResponseHeaders(200, body.length);
        try (OutputStream os = exchange.getResponseBody()) {
            os.write(body);
        }
    }
}

@Component
@HttpJdkFilterPattern("/api/*")
public class LoggingFilter extends Filter {

    @Override
    public void doFilter(HttpExchange exchange, Chain chain) throws IOException {
        System.out.println("Request: " + exchange.getRequestURI());
        chain.doFilter(exchange);
    }

    @Override
    public String description() {
        return "Logging Filter";
    }
}

@Component
@HttpJdkAuthenticatorPattern("/admin/*")
@HttpJdkAuthenticatorRealm("admin")
public class AdminAuthenticator extends BasicAuthenticator {

    public AdminAuthenticator() {
        super("admin");
    }

    @Override
    public boolean checkCredentials(String username, String password) {
        return "admin".equals(username) && "secret".equals(password);
    }
}

@Component
@HttpJdkResource(pattern = "/static/*", prefix = "/web")
public class StaticResources {
    // Marker component; the service object is never used.
}

Provide-Capability: osgi.implementation;
 osgi.implementation="osgi.http.jdk";
 uses:="org.osgi.service.jdkhttp.whiteboard,
        org.osgi.service.jdkhttp.runtime,
        org.osgi.service.jdkhttp.runtime.dto";
 version:Version=""
